def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for k, o in opponents_status.items():
        if o and o.get('alive', False):
            alive_opps.append(o)

    if not alive_opps:
        return float(min(budget, DAILY_SALARY * 0.4))

    # Use only yesterday's previous_trace for immediate reaction
    yesterday_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {})
        if isinstance(prev, dict):
            b = prev.get('bid', None)
            if b is not None:
                try:
                    yesterday_bids.append(float(b))
                except Exception:
                    pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Supply pressure: map supply into [0,1]
    # Lower supply => higher price pressure
    if MAX_SUPPLY > MIN_SUPPLY:
        pressure = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    else:
        pressure = 0.5
    if pressure < 0.0:
        pressure = 0.0
    if pressure > 1.0:
        pressure = 1.0

    # Base bid: competitive but not maxing out
    # When hp is low or already accruing no-water days, bid higher.
    if hp <= 2:
        base_mult = 0.95
    elif hp <= 3:
        base_mult = 0.80
    else:
        base_mult = 0.55

    # If opponents were bidding very high yesterday, we may need to match slightly.
    # Cindy bid 0 and died; ignore 0 bids.
    effective_highest = highest_prev_bid if highest_prev_bid >= DAILY_SALARY * 0.2 else 0.0

    target = DAILY_SALARY * base_mult

    if effective_highest > 0.0:
        if effective_highest >= DAILY_SALARY * 0.85:
            # They were near-max; bid to secure at least one share
            target = max(target, min(DAILY_SALARY * 0.75, effective_highest * 0.98))
        else:
            # Moderate competition; bid slightly above their typical high
            target = max(target, min(DAILY_SALARY * 0.65, effective_highest * 0.85))

    # Adjust with supply pressure
    target = target * (0.85 + 0.30 * pressure)

    # Convert to water units intuition: if supply is below requirement, we must fight more.
    if supply < float(WATER_REQ):
        target = max(target, DAILY_SALARY * 0.70)

    # Ensure we don't exceed budget
    if budget <= 0.0:
        return 0.0

    # If we're already on no-water streak, increase urgency
    if no_water_days >= 2:
        target = max(target, DAILY_SALARY * 0.75)

    bid = float(min(budget, target))
    if bid < 0.0:
        bid = 0.0
    return bid

