            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                needy_count += 1
            prev = opp.get('previous_trace', {})
            if prev:
                bid = prev.get('bid')
                if bid is not None:
                    prev_bids.append(float(bid))
                    if float(bid) > 0:
                        strong_prev_bids.append(float(bid))

    if not alive_opponents:
        return float(min(budget, 1.0))

    units = int(supply // WATER_REQ)
    scarcity = units <= 1
    medium_tight = units <= 2

    highest_prev = max(prev_bids) if prev_bids else 0.0
    active_high = max(strong_prev_bids) if strong_prev_bids else 0.0

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1
    if no_water_days >= 2:
        danger += 3
    elif no_water_days >= 1:
        danger += 2

    if scarcity:
        base = 78.0
    elif medium_tight:
        base = 42.0
    else:
        base = 18.0

    if active_high >= 120:
        if danger >= 4:
            bid = 118.0
        elif scarcity:
            bid = 72.0
        else:
            bid = 12.0
    elif active_high >= 95:
        if danger >= 3:
            bid = min(108.0, active_high + 2.0)
        elif scarcity:
            bid = 66.0
        else:
            bid = 16.0
    elif active_high > 0:
        if danger >= 3:
            bid = max(base + 18.0, active_high + 1.5)
        else:
            bid = max(base, active_high * 0.72)
    else:
        bid = base

    if needy_count >= 2 and scarcity:
        bid += 10.0
    elif needy_count >= 1 and medium_tight:
        bid += 5.0

    if day >= 8 and budget > DAILY_SALARY * 2:
        bid += 8.0

    reserve = 0.0
    if day <= 7:
        reserve = max(0.0, (10 - day) * 6.0)
    max_affordable = max(0.0, budget - reserve)
    if danger >= 4:
        max_affordable = budget

    bid = min(bid, max_affordable)
    bid = min(bid, budget)
    if danger >= 4:
        bid = max(bid, min(budget, 88.0))
    elif danger >= 2 and scarcity:
        bid = max(bid, min(budget, 62.0))

    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = int(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    # Base bid as fraction of salary
    if hp <= 3 or no_water_days >= 2:
        base = 0.8 * DAILY_SALARY
    elif hp <= 5:
        base = 0.6 * DAILY_SALARY
    else:
        base = 0.4 * DAILY_SALARY

    # Supply adjustment
    median_supply = (MAX_SUPPLY + MIN_SUPPLY) / 2
    if supply < median_supply:
        base *= 1.2
    elif supply > median_supply:
        base *= 0.9

    # Consider opponents' past behavior from previous_trace
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    high_bidders = 0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            if prev['bid'] > DAILY_SALARY * 0.6:
                high_bidders += 1

    if high_bidders >= 2:
        base = min(budget, base * 1.3)
    elif high_bidders == 1:
        base = min(budget, base * 1.1)

    # Ensure at least 1 if in danger of no water
    bid = min(base, budget)
    if no_water_days > 0 and bid < 1:
        bid = min(budget, 1)

    return float(bid)
